/* JavaScript Node ACM模式 控制台输入获取 */
const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

const lines = [];
rl.on("line", (line) => {
  lines.push(line);

  if (lines.length === 2) {
    let [n, m] = lines.map(Number);
    console.log(getResult(n, m));
    lines.length = 0;
  }
});

function getResult(n, m) {
  // 若输入不合法，返回-1
  if (n < 3 || n > 7 || m < 0) return -1;

  // 提前计算好0~9的N次方, 避免后续进行重复计算
  const powN = {};
  for (let i = 0; i <= 9; i++) {
	  powN[i] = Math.pow(i, n);
  }

  // N位数的最小值
  const minNum = Math.pow(10, n - 1);
  // N位数的最大值 + 1
  const maxNum = Math.pow(10, n);

  // 记录当前水仙花数
  let ans = 0;

  // 记录当前水仙花数的索引
  let idx = 0;

  // 遍历所有的N位数
  for (let num = minNum; num < maxNum; num++) {
	// 记录num各位数字的N次方之和
	let sum = 0;

	// 遍历num的每一位数字
	for(let c of (num + "")) {
		sum += powN[c];
	}

    // 判断num是否为水仙花数
    if (num == sum) {
      ans = num;
	  // 如果num刚好是N位数的第m个水仙花数，则直接返回，否则继续查找
      if (idx++ == m) return ans;
    }
  }

  // 若m大于水仙花数的个数，返回最后一个水仙花数和m的乘积
  return ans * m;
}

